// Extraire les données du job
const input = $input.first().json;

let verses = [];
let body = input;

// Structure webhook standard
if (input.body && Array.isArray(input.body.verses)) {
  verses = input.body.verses;
  body = input.body;
} else if (Array.isArray(input.verses)) {
  verses = input.verses;
} else if (input.body && typeof input.body === 'string') {
  try {
    const parsed = JSON.parse(input.body);
    if (Array.isArray(parsed.verses)) {
      verses = parsed.verses;
      body = parsed;
    }
  } catch(e) {}
}

return [{
  json: {
    jobId: body.job_id || input.job_id,
    project: body.project || input.project,
    textName: body.text_name || input.text_name,
    chapter: body.chapter || input.chapter,
    refFormat: body.ref_format || input.ref_format || 'chapter_verse',
    targetLanguage: body.target_language || input.target_language || 'fr',
    apiKey: body.api_key || input.api_key,
    openaiApiKey: body.openai_api_key || input.openai_api_key,
    verses: verses,
    versesCount: verses.length
  }
}];

// Passer les données originales
const prevData = $('Parse Input').first().json;
return [{ json: prevData }];

// Convertir les versets en items pour la boucle
const input = $input.first().json;

const items = input.verses.map((verse, index) => {
  // Construire la référence selon le format
  let reference;
  if (input.refFormat === 'chapter_only') {
    reference = `${input.textName} ${input.chapter}`;
  } else {
    reference = `${input.textName} ${input.chapter}:${verse.verse || index + 1}`;
  }

  return {
    json: {
      verseIndex: index,
      verseId: verse.id,
      verseNumber: verse.verse || 0,
      verseText: verse.hebrew_text || verse.text || '',
      reference: reference,
      totalVerses: input.verses.length,
      jobId: input.jobId,
      project: input.project,
      textName: input.textName,
      chapter: input.chapter,
      refFormat: input.refFormat,
      targetLanguage: input.targetLanguage,
      apiKey: input.apiKey,
      openaiApiKey: input.openaiApiKey
    }
  };
});

return items;

